// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { computeGraphLayout } from "../../../main/frontend/graph-explorer/graph-layout-engine.ts";
import { startGraphLayout } from "../../../main/frontend/graph-explorer/graph-layout-client.ts";

test("normal layout preserves pinned coordinates through every refinement", async () => {
  const graph = { revision: 1, nodes: [
    {id: "pinned", label: "Pinned", kind: "iri", x: 100, y: 100, pinned: true},
    {id: "free", label: "Free", kind: "iri", x: 100, y: 100},
  ], edges: [{id: "edge", source: "pinned", target: "free", predicate: "urn:p", label: "p"}] };
  const before = structuredClone(graph);
  const result = await computeGraphLayout(graph);
  assert.deepEqual(result.positions.get("pinned"), { x: 100, y: 100 });
  assert.deepEqual(graph, before, "the worker must not mutate its caller's graph");
});

test("cancelling a layout terminates its worker and ignores late replies", async () => {
  let terminated = 0;
  const worker = { postMessage() {}, terminate() { terminated++; } };
  const job = startGraphLayout({nodes: [], edges: [], revision: 1}, {}, () => worker);
  const staleHandler = worker.onmessage;
  const rejection = assert.rejects(job.promise, {name: "AbortError"});
  job.cancel();
  staleHandler({data: {result: {positions: new Map(), bends: new Map()}}});
  job.cancel();
  await rejection;
  assert.equal(terminated, 1);
  assert.equal(worker.onmessage, null);
});

test("completed and failed layout jobs release worker resources", async () => {
  for (const failure of [false, true]) {
    let terminated = 0;
    const worker = { postMessage() {}, terminate() { terminated++; } };
    const job = startGraphLayout({nodes: [], edges: [], revision: 1}, {}, () => worker);
    if (failure) {
      const rejection = assert.rejects(job.promise, /worker failed/);
      worker.onerror();
      await rejection;
    } else {
      const result = {positions: new Map(), bends: new Map()};
      worker.onmessage({data: {result}});
      assert.deepEqual(await job.promise, result);
    }
    job.cancel();
    assert.equal(terminated, 1);
  }
});
